  "claims": [
    {
      "claim": "Direct human absolute or estimated oral bioavailability values for the most transferable steroid contexts are below 20%: testosterone 2-8% (C01), abiraterone acetate <10% fasted (C07, C14, C20), testosterone undecanoate 6.8 ± 3.3% (C10, C22), thienorphine very low (C15), mometasone <1% (C09), fulvestrant low or poor (C04, C16, C18, C19).",
      "card_ids": ["C01","C07","C14","C20","C10","C22","C15","C09","C04","C16","C18","C19"]
    },
    {
      "claim": "L3 oral exposure records show only pg/mL-level Cmax for structurally related steroid phenols: estradiol 13.3 pg/mL after 0.625 mg oral (C50), ethinylestradiol 58.5 to 104 pg/mL (C39, C43, C49), levonorgestrel 8.25 pg/mL (C41). These low exposures relative to dose are consistent with extensive first-pass loss and low F; none reports a bioavailability fraction or supports F ≥ 20%.",
      "card_ids": ["C50","C39","C43","C49","C41"]
    },
    {
      "claim": "Positive-sounding statements are non-absolute or different-molecule and do not establish F ≥ 20% for the query: thienorphine better than buprenorphine (C24, C25) conflicts with its direct very-low finding (C15), DMAU orally bioavailable (C36) conflicts with poor and variable reports (C03, C34), Casodex 72% at 1 mg/kg in male rats (C38) is dose-dependent and a different scaffold.",
      "card_ids": ["C24","C25","C36","C38"]
    },
    {
      "claim": "The query is a neutral lipophilic steroid phenol with a tertiary alcohol and no basic center (logD 4.14), closely matching the estradiol and testosterone scaffolds whose oral F is low; no affirmative threshold-relevant evidence supports F ≥ 20%.",
      "card_ids": ["C01","C07","C10","C50"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C39","C40","C41","C42","C43","C44","C45","C46","C47","C48","C49","C50"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule itself; the low prediction relies on transfer from structurally related steroid contexts.",
    "L3 exposure records report Cmax and related exposure but not bioavailability fractions, so they cannot independently establish F relative to the 20% threshold.",
    "No query-specific first-pass metabolism, solubility, or dissolution data are available; phenol conjugation and high lipophilicity are inferred but not directly measured.",
    "Some records are relative comparisons or involve different molecules, species, doses, or formulations (C24, C25, C36, C38), limiting their transferability."
  ],
  "decision_summary": "Predicted low (F < 20%) because the most transferable steroid contexts report low absolute oral bioavailability and the L3 exposure records show only pg/mL-level oral exposures consistent with extensive first-pass loss; no affirmative evidence supports F ≥ 20%."
}

